{"command":"mkdir -p /tmp/hashtest && cd /tmp/hashtest
cat << 'EOF' > go.mod
module hashtest
go 1.21
EOF

cat << 'EOF' > main.go
package main

import (
	"crypto/sha256"
	"encoding/base64"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"sort"
)

func Hash1(files []string, open func(string) (io.ReadCloser, error)) (string, error) {
	h := sha256.New()
	files = append([]string(nil), files...)
	sort.Strings(files)
	for _, file := range files {
		if path := filepath.ToSlash(file); path != file {
			return "", fmt.Errorf("filenames must use forward slashes")
		}
		r, err := open(file)
		if err != nil {
			return "", err
		}
		hf := sha256.New()
		_, err = io.Copy(hf, r)
		r.Close()
		if err != nil {
			return "", err
		}
		fmt.Fprintf(h, "%x  %s\n", hf.Sum(nil), file)
	}
	return "h1:" + base64.StdEncoding.EncodeToString(h.Sum(nil)), nil
}

func main() {
	files := []string{"20230101000000_init.sql"}
	res, _ := Hash1(files, func(name string) (io.ReadCloser, error) {
		return os.Open("/tmp/sumtest/" + name)
	})
	fmt.Println("dirhash res:", res)
}
EOF

go run main.go
