	content, _ := os.ReadFile("/tmp/sumtest/" + fn)
	fileHash := "h1:+wAbcEB499TINd3uPAteM7+f41M4Mp8lrV7Iuox6ekw="

	fileHashBytes, _ := base64.StdEncoding.DecodeString("+" + "wAbcEB499TINd3uPAteM7+f41M4Mp8lrV7Iuox6ekw=")

	inputs := [][]byte{
		[]byte(fn + " " + fileHash),
		[]byte(fn + " " + fileHash + "\n"),
		[]byte(fileHash),
		[]byte(fileHash + "\n"),
		append([]byte(fn), content...),
		append([]byte(fn+"\n"), content...),
		content,
	}

	for _, in := range inputs {
		// sha256
