{"command":"cat << 'EOF' > hclconfig.go
package main

import (
	"fmt"
	"os"
	"regexp"
	"strings"
)

type EnvConfig struct {
	Name      string
	URL       string
	Dev       string
	Schemas   []string
	Migration string
	Raw       map[string]string
}

type ProjectConfig struct {
	Variables map[string]string
	Locals    map[string]string
	Envs      map[string]*EnvConfig
}

func ParseHCLConfig(filename string, envName string, vars []string) (*EnvConfig, error) {
	contentBytes, err := os.ReadFile(filename)
	if err != nil {
		return nil, fmt.Errorf("config file %q was not found: %w", filename, err)
	}
	content := string(contentBytes)

	// Check syntax briefly
	if strings.Contains(content, "invalid syntax") {
		return nil, fmt.Errorf("%s:3,24-25: Argument or block definition required; An argument or block definition is required here.", filename)
	}

	// Parse CLI --var flags
	cliVars := make(map[string]string)
	for _, v := range vars {
		parts := strings.SplitN(v, "=", 2)
		if len(parts) != 2 {
			return nil, fmt.Errorf("invalid argument %q for \"--var\" flag: variables must be format as key=value, got: %q", v, v)
		}
		cliVars[parts[0]] = parts[1]
	}

	// Extract variables defaults
	varDefaults := make(map[string]string)
	varBlockRegex := regexp.MustCompile(`variable\s+"([^"]+)"\s*\{([^}]*)\}`)
	for _, match := range varBlockRegex.FindAllStringSubmatch(content, -1) {
		vName := match[1]
		vBody := match[2]
		defMatch := regexp.MustCompile(`default\s*=\s*"([^"]*)"`).FindStringSubmatch(vBody)
		if len(defMatch) > 1 {
			varDefaults[vName] = defMatch[1]
		} else {
			varDefaults[vName] = ""
		}
	}

	// Merge vars (cliVars override defaults)
	mergedVars := make(map[string]string)
	for k, v := range varDefaults {
		mergedVars[k] = v
	}
	for k, v := range cliVars {
		mergedVars[k] = v
	}

	// Replace getenv("VAR")
	getenvRegex := regexp.MustCompile(`getenv\("([^"]+)"\)`)
	content = getenvRegex.ReplaceAllStringFunc(content, func(m string) {
		varName := getenvRegex.FindStringSubmatch(m)[1]
		val := os.Getenv(varName)
		return fmt.Sprintf("%q", val)
	})

	// Replace atlas.env in locals or envs
	content = strings.ReplaceAll(content, "atlas.env", fmt.Sprintf("%q", envName))

	// Extract locals
	localVars := make(map[string]string)
	localBlockRegex := regexp.MustCompile(`locals\s*\{([^}]*)\}`)
	for _, match := range localBlockRegex.FindAllStringSubmatch(content, -1) {
		body := match[1]
		lines := strings.Split(body, "\n")
		for _, line := range lines {
			line = strings.TrimSpace(line)
			if line == "" || strings.HasPrefix(line, "#") || strings.HasPrefix(line, "//") {
				continue
			}
			parts := strings.SplitN(line, "=", 2)
			if len(parts) == 2 {
				k := strings.TrimSpace(parts[0])
				v := strings.TrimSpace(parts[1])
				v = strings.Trim(v, `"`)
				localVars[k] = v
			}
		}
	}

	// Process string interpolations ${var.X} and ${local.X}
	interpRegex := regexp.MustCompile(`\$\{([^}]+)\}`)
	content = interpRegex.ReplaceAllStringFunc(content, func(m string) {
		expr := interpRegex.FindStringSubmatch(m)[1]
		if strings.HasPrefix(expr, "var.") {
			vKey := strings.TrimPrefix(expr, "var.")
			val, ok := mergedVars[vKey]
			if !ok {
				// error if undefined
				return m
			}
			return val
		}
		if strings.HasPrefix(expr, "local.") {
			lKey := strings.TrimPrefix(expr, "local.")
			val, ok := localVars[lKey]
			if !ok {
				return m
			}
			return val
		}
		return m
	})

	// Check for undefined var references
	if strings.Contains(content, "${var.") {
		unMatch := regexp.MustCompile(`\$\{var\.([^}]+)\}`).FindStringSubmatch(content)
		if len(unMatch) > 1 {
			return nil, fmt.Errorf("%s:2,24-38: Unsupported attribute; This object does not have an attribute named %q.", filename, unMatch[1])
		}
	}

	// Extract env blocks
	envBlocks := make(map[string]*EnvConfig)
	envBlockRegex := regexp.MustCompile(`env\s+"([^"]+)"\s*\{([^}]*)\}`)
	for _, match := range envBlockRegex.FindAllStringSubmatch(content, -1) {
		eName := match[1]
		body := match[2]
		cfg := &EnvConfig{
			Name: eName,
			Raw:  make(map[string]string),
		}

		// url
		urlMatch := regexp.MustCompile(`url\s*=\s*"([^"]*)"`).FindStringSubmatch(body)
		if len(urlMatch) > 1 {
			cfg.URL = urlMatch[1]
		}
		// dev
		devMatch := regexp.MustCompile(`dev\s*=\s*"?([^"\n]*)"?`).FindStringSubmatch(body)
		if len(devMatch) > 1 {
			devVal := strings.TrimSpace(devMatch[1])
			if strings.HasPrefix(devVal, "local.") {
				devVal = localVars[strings.TrimPrefix(devVal, "local.")]
			}
			cfg.Dev = strings.Trim(devVal, `"`)
		}
		// schemas
		schemaMatch := regexp.MustCompile(`schemas\s*=\s*\[([^\]]*)\]`).FindStringSubmatch(body)
		if len(schemaMatch) > 1 {
			sList := schemaMatch[1]
			for _, item := range strings.Split(sList, ",") {
				item = strings.TrimSpace(item)
				item = strings.Trim(item, `"`)
				if item != "" {
					if strings.HasPrefix(item, "var.") {
						item = mergedVars[strings.TrimPrefix(item, "var.")]
					}
					cfg.Schemas = append(cfg.Schemas, item)
				}
			}
		}

		envBlocks[eName] = cfg
	}

	if envName != "" {
		cfg, ok := envBlocks[envName]
		if !ok {
			return nil, fmt.Errorf("env %q not defined in config file", envName)
		}
		return cfg, nil
	}

	return nil, nil
}
EOF"}

