		if len(devMatch) > 1 {
			devVal := strings.TrimSpace(devMatch[1])
			if strings.HasPrefix(devVal, "local.") {
				devVal = localVars[strings.TrimPrefix(devVal, "local.")]
			}
			cfg.Dev = strings.Trim(devVal, `"`)
		}
