		schemaMatch := regexp.MustCompile(`schemas\s*=\s*\[([^\]]*)\]`).FindStringSubmatch(body)
		if len(schemaMatch) > 1 {
			sList := schemaMatch[1]
			for _, item := range strings.Split(sList, ",") {
