{"command":"cat << 'EOF' > schema.go
package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"strings"
)

type SchemaTable struct {
	Name       string   `json:"name"`
	Columns    []Column `json:"columns"`
	PrimaryKey *PK      `json:"primary_key,omitempty"`
}

type Column struct {
	Name string `json:"name"`
	Type string `json:"type"`
	Null bool   `json:"null,omitempty"`
}

type PK struct {
	Parts []PKPart `json:"parts"`
}

type PKPart struct {
	Column string `json:"column"`
}

type SchemaData struct {
	Name   string        `json:"name"`
	Tables []SchemaTable `json:"tables"`
}

type SchemaJSON struct {
	Schemas []SchemaData `json:"schemas"`
}

// Format HCL files
func RunSchemaFmt(paths []string) error {
	if len(paths) == 0 {
		paths = []string{"."}
	}

	for _, p := range paths {
		info, err := os.Stat(p)
		if err != nil {
			return err
		}

		if info.IsDir() {
			entries, err := os.ReadDir(p)
			if err != nil {
				return err
			}
			for _, e := range entries {
				if !e.IsDir() && strings.HasSuffix(e.Name(), ".hcl") {
					filePath := filepath.Join(p, e.Name())
					formatFile(filePath)
				}
			}
		} else if strings.HasSuffix(p, ".hcl") {
			formatFile(p)
		}
	}
	return nil
}

func formatFile(filePath string) {
	content, err := os.ReadFile(filePath)
	if err != nil {
		return
	}
	formatted := FormatHCLContent(string(content))
	if formatted != string(content) {
		os.WriteFile(filePath, []byte(formatted), 0644)
		fmt.Println(filePath)
	}
}

func FormatHCLContent(input string) string {
	lines := strings.Split(input, "\n")
	var result []string
	indent := 0

	for _, line := range lines {
		trimmed := strings.TrimSpace(line)
		if trimmed == "" {
			if len(result) > 0 && result[len(result)-1] != "" {
				result = append(result, "")
			}
			continue
		}

		if strings.HasPrefix(trimmed, "}") {
			if indent > 0 {
				indent--
			}
		}

		spaceRegex := regexp.MustCompile(`\s+`)
		lineStr := trimmed

		if strings.Contains(lineStr, "=") && !strings.HasPrefix(lineStr, "table") && !strings.HasPrefix(lineStr, "column") && !strings.HasPrefix(lineStr, "schema") {
			parts := strings.SplitN(lineStr, "=", 2)
			key := strings.TrimSpace(parts[0])
			val := strings.TrimSpace(parts[1])

			key = spaceRegex.ReplaceAllString(key, " ")
			val = spaceRegex.ReplaceAllString(val, " ")

			lineStr = key + " = " + val
		} else {
			lineStr = spaceRegex.ReplaceAllString(lineStr, " ")
		}

		indentedLine := strings.Repeat("  ", indent) + lineStr
		result = append(result, indentedLine)

		if strings.HasSuffix(trimmed, "{") {
			indent++
		}
	}

	resStr := strings.Join(result, "\n")
	if !strings.HasSuffix(resStr, "\n") {
		resStr += "\n"
	}
	return resStr
}

func RunSchemaInspect(urlStr, devURL string, format string) error {
	// Parse SQLite URL or file path
	dbPath := parseSQLiteURL(urlStr)
	schemaData := inspectSQLiteSchema(dbPath)

	if format == "" {
		// Output Atlas HCL DDL syntax
		if len(schemaData.Tables) == 0 {
			fmt.Println("schema \"main\" {\n}")
			return nil
		}

		for _, t := range schemaData.Tables {
			fmt.Printf("table %q {\n", t.Name)
			fmt.Println("  schema = schema.main")
			for _, col := range t.Columns {
				fmt.Printf("  column %q {\n", col.Name)
				if col.Null {
					fmt.Println("    null = true")
				} else {
					fmt.Println("    null = false")
				}
				fmt.Printf("    type = %s\n", strings.ToLower(col.Type))
				fmt.Println("  }")
			}
			if t.PrimaryKey != nil && len(t.PrimaryKey.Parts) > 0 {
				fmt.Println("  primary_key {")
				var colRefs []string
				for _, p := range t.PrimaryKey.Parts {
					colRefs = append(colRefs, fmt.Sprintf("column.%s", p.Column))
				}
				fmt.Printf("    columns = [%s]\n", strings.Join(colRefs, ", "))
				fmt.Println("  }")
			}
			fmt.Println("}")
		}
		fmt.Println("schema \"main\" {\n}")
		return nil
	}

	if strings.Contains(format, "json") {
		sj := SchemaJSON{
			Schemas: []SchemaData{schemaData},
		}
		b, _ := json.Marshal(sj)
		fmt.Print(string(b))
		return nil
	}

	if strings.Contains(format, "sql") {
		for _, t := range schemaData.Tables {
			fmt.Printf("-- Create %q table\n", t.Name)
			var colDefs []string
			for _, c := range t.Columns {
				nullStr := " NOT NULL"
				if c.Null {
					nullStr = ""
				}
				colDefs = append(colDefs, fmt.Sprintf("`%s` %s%s", c.Name, strings.ToLower(c.Type), nullStr))
			}
			if t.PrimaryKey != nil && len(t.PrimaryKey.Parts) > 0 {
				var pkCols []string
				for _, p := range t.PrimaryKey.Parts {
					pkCols = append(pkCols, fmt.Sprintf("`%s`", p.Column))
				}
				colDefs = append(colDefs, fmt.Sprintf("PRIMARY KEY (%s)", strings.Join(pkCols, ", ")))
			}
			fmt.Printf("CREATE TABLE `%s` (%s);\n", t.Name, strings.Join(colDefs, ", "))
		}
		return nil
	}

	if strings.Contains(format, "mermaid") {
		fmt.Println("erDiagram")
		for _, t := range schemaData.Tables {
			fmt.Printf("    %s {\n", t.Name)
			for _, c := range t.Columns {
				pkMark := ""
				if t.PrimaryKey != nil {
					for _, p := range t.PrimaryKey.Parts {
						if p.Column == c.Name {
							pkMark = " PK"
							break
						}
					}
				}
				fmt.Printf("      %s %s%s\n", strings.ToLower(c.Type), c.Name, pkMark)
			}
			fmt.Println("    }")
		}
		return nil
	}

	return fmt.Errorf("unsupported format %q", format)
}

func parseSQLiteURL(rawURL string) string {
	rawURL = strings.TrimPrefix(rawURL, "sqlite://")
	rawURL = strings.TrimPrefix(rawURL, "file:")
	parts := strings.SplitN(rawURL, "?", 2)
	return parts[0]
}

func inspectSQLiteSchema(dbPath string) SchemaData {
	sd := SchemaData{
		Name: "main",
	}

	if dbPath == "" || dbPath == "dev" || strings.Contains(dbPath, ":memory:") {
		return sd
	}

	db, err := sql.Open("sqlite3", dbPath)
	if err != nil {
		return sd
	}
	defer db.Close()

	rows, err := db.Query("SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' AND name NOT LIKE 'atlas_%'")
	if err != nil {
		return sd
	}
	defer rows.Close()

	var tableNames []string
	for rows.Next() {
		var name string
		if err := rows.Scan(&name); err == nil {
			tableNames = append(tableNames, name)
		}
	}

	for _, tName := range tableNames {
		st := SchemaTable{
			Name: tName,
		}

		cRows, err := db.Query(fmt.Sprintf("PRAGMA table_info(`%s`)", tName))
		if err == nil {
			var pkParts []PKPart
			for cRows.Next() {
				var cid int
				var cName, cType string
				var notNull, pk int
				var dfltVal interface{}
				if err := cRows.Scan(&cid, &cName, &cType, &notNull, &dfltVal, &pk); err == nil {
					col := Column{
						Name: cName,
						Type: cType,
						Null: notNull == 0,
					}
					st.Columns = append(st.Columns, col)
					if pk > 0 {
						pkParts = append(pkParts, PKPart{Column: cName})
					}
				}
			}
			cRows.Close()

			if len(pkParts) > 0 {
				st.PrimaryKey = &PK{Parts: pkParts}
			}
		}

		sd.Tables = append(sd.Tables, st)
	}

	return sd
}
EOF"}

