	d := strings.TrimPrefix(rawURL, "file://")
	d = strings.TrimPrefix(d, "file:")
	if d == "" {
		d = "migrations"
	}
	return d
}

func ReadMigrationDir(dirPath string) ([]MigFile, error) {
	entries, err := os.ReadDir(dirPath)
	if err != nil {
		return nil, fmt.Errorf("stat %s: no such file or directory", dirPath)
	}

	var files []MigFile
	for _, e := range entries {
		if e.IsDir() {
			continue
		}
		if e.Name() == "atlas.sum" {
			continue
		}
		if strings.HasSuffix(e.Name(), ".sql") {
			c, err := os.ReadFile(filepath.Join(dirPath, e.Name()))
			if err != nil {
				return nil, err
			}
			files = append(files, MigFile{
				Name:    e.Name(),
				Content: c,
			})
		}
	}

	sort.Slice(files, func(i, j int) bool {
		return files[i].Name < files[j].Name
	})

	return files, nil
}

func HashDirectory(files []MigFile) (string, string) {
	sort.Slice(files, func(i, j int) bool {
		return files[i].Name < files[j].Name
	})

	var dirConcat strings.Builder
	var lines []string

	for _, f := range files {
		hf := sha256.Sum256(append([]byte(f.Name), f.Content...))
		b64 := base64.StdEncoding.EncodeToString(hf[:])
		lines = append(lines, fmt.Sprintf("%s h1:%s\n", f.Name, b64))
		dirConcat.WriteString(f.Name + b64)
	}

	dirHash := sha256.Sum256([]byte(dirConcat.String()))
	dirB64 := "h1:" + base64.StdEncoding.EncodeToString(dirHash[:])

	sumFileContent := dirB64 + "\n" + strings.Join(lines, "")
	return dirB64, sumFileContent
}

func RunMigrateHash(dirURL string) error {
	dirPath := parseDirURL(dirURL)
	files, err := ReadMigrationDir(dirPath)
	if err != nil {
		return err
	}

	_, sumContent := HashDirectory(files)
	sumPath := filepath.Join(dirPath, "atlas.sum")
	return os.WriteFile(sumPath, []byte(sumContent), 0644)
}

func RunMigrateValidate(dirURL string) error {
	dirPath := parseDirURL(dirURL)
	sumPath := filepath.Join(dirPath, "atlas.sum")

	sumContentBytes, err := os.ReadFile(sumPath)
	if err != nil {
		fmt.Println("You have a checksum error in your migration directory.")
		fmt.Println("Please check your migration files and run 'atlas migrate hash' to re-hash the contents\n")
		return fmt.Errorf("checksum file not found")
	}

	sumLines := strings.Split(strings.TrimSpace(string(sumContentBytes)), "\n")
	if len(sumLines) == 0 {
		fmt.Println("You have a checksum error in your migration directory.")
		fmt.Println("Please check your migration files and run 'atlas migrate hash' to re-hash the contents\n")
		return fmt.Errorf("checksum mismatch")
	}

	expectedDirHash := sumLines[0]
	fileHashMap := make(map[string]string)
	var expectedFileOrder []string

	for _, line := range sumLines[1:] {
		line = strings.TrimSpace(line)
		if line == "" {
			continue
		}
		parts := strings.SplitN(line, " ", 2)
		if len(parts) == 2 {
			fileHashMap[parts[0]] = parts[1]
			expectedFileOrder = append(expectedFileOrder, parts[0])
		}
	}

	files, err := ReadMigrationDir(dirPath)
	if err != nil {
		return err
	}

	currentFileMap := make(map[string]MigFile)
	for _, f := range files {
		currentFileMap[f.Name] = f
	}

	var mismatches []string
	lineNum := 2

	for _, expectedName := range expectedFileOrder {
		curFile, exists := currentFileMap[expectedName]
		if !exists {
			mismatches = append(mismatches, fmt.Sprintf("\tL%d: %s was removed", lineNum, expectedName))
		} else {
			expectedHash := fileHashMap[expectedName]
			hf := sha256.Sum256(append([]byte(curFile.Name), curFile.Content...))
			calcHash := "h1:" + base64.StdEncoding.EncodeToString(hf[:])
			if calcHash != expectedHash {
				mismatches = append(mismatches, fmt.Sprintf("\tL%d: %s was edited", lineNum, expectedName))
			}
		}
		lineNum++
	}

	for _, f := range files {
		if _, expected := fileHashMap[f.Name]; !expected {
			mismatches = append(mismatches, fmt.Sprintf("\tL%d: %s was added", lineNum, f.Name))
			lineNum++
		}
	}

	if len(mismatches) > 0 {
		fmt.Println("You have a checksum error in your migration directory.\n")
		for _, m := range mismatches {
			fmt.Println(m)
		}
		fmt.Println("\nPlease check your migration files and run 'atlas migrate hash' to re-hash the contents\n")
		return fmt.Errorf("checksum mismatch")
	}

	calcDirHash, _ := HashDirectory(files)
	if calcDirHash != expectedDirHash {
		fmt.Println("You have a checksum error in your migration directory.")
		fmt.Println("Please check your migration files and run 'atlas migrate hash' to re-hash the contents\n")
		return fmt.Errorf("checksum mismatch")
	}

	return nil
}

