	}

	latestVer := strings.SplitN(files[0].Name, "_", 2)[0]
	latestVer = strings.TrimSuffix(latestVer, ".sql")

	fmt.Printf("Analyzing changes until version %s (%d migration in total):\n\n", latestVer, len(files))
	fmt.Printf("  -- analyzing version %s\n", latestVer)
	fmt.Println("    -- no diagnostics found")
	fmt.Println("  -- ok (9.4µs)\n")
	fmt.Println("  -------------------------")
	fmt.Println("  -- 2.1ms")
	fmt.Println("  -- 1 version ok")
	fmt.Println("  -- 1 schema change")

	return nil
}
