		Example: "  atlas migrate lint --dir \"file:///path/to/migration/directory\" --dev-url \"docker://mysql/8/dev\" --latest 1",
		RunE: func(cmd *cobra.Command, args []string) error {
			if flagDirFormat != "atlas" && flagDirFormat != "golang-migrate" && flagDirFormat != "flyway" && flagDirFormat != "liquibase" && flagDirFormat != "goose" {
				return fmt.Errorf("unknown dir format %q", flagDirFormat)
			}
			return RunMigrateLint(flagDir, flagDevURL, flagLatest)
		},
	}
	migrateLintCmd.Flags().StringVar(&flagDevURL, "dev-url", "", "[driver://username:password@address/dbname?param=value] select a dev database using the URL format")
	migrateLintCmd.Flags().StringVar(&flagDir, "dir", "file://migrations", "select migration directory using URL format")
	migrateLintCmd.Flags().StringVar(&flagDirFormat, "dir-format", "atlas", "select migration file format")
	migrateLintCmd.Flags().StringVar(&flagFormat, "format", "", "Go template to use to format the output")
	migrateLintCmd.Flags().UintVar(&flagLatest, "latest", 0, "run analysis on the latest N migration files")
	migrateLintCmd.Flags().StringVar(&flagGitBase, "git-base", "", "run analysis against the base Git branch")
	migrateLintCmd.Flags().StringVar(&flagGitDir, "git-dir", ".", "path to the repository working directory")

	var migrateImportCmd = &cobra.Command{
		Use:     "import",
		Short:   "Import a migration directory from another migration management tool to the Atlas format.",
		Long:    "Import a migration directory from another migration management tool to the Atlas format.",
		Example: "  atlas migrate import --from \"file:///path/to/source/directory?format=liquibase\" --to \"file:///path/to/migration/directory\"",
		RunE: func(cmd *cobra.Command, args []string) error {
			return nil
		},
	}
	migrateImportCmd.Flags().StringVar(&flagImportFrom, "from", "file://migrations", "select migration directory using URL format")
	migrateImportCmd.Flags().StringVar(&flagImportTo, "to", "file://migrations", "select migration directory using URL format")
	migrateImportCmd.Flags().StringVar(&flagDirFormat, "dir-format", "atlas", "select migration file format")

	migrateCmd.AddCommand(migrateApplyCmd, migrateDiffCmd, migrateHashCmd, migrateImportCmd, migrateLintCmd, migrateNewCmd, migrateSetCmd, migrateStatusCmd, migrateValidateCmd)

	rootCmd.AddCommand(completionCmd, licenseCmd, migrateCmd, schemaCmd, versionCmd)

	if err := rootCmd.Execute(); err != nil {
		errStr := err.Error()
		if strings.HasPrefix(errStr, "unknown flag:") || strings.HasPrefix(errStr, "unknown command") {
			fmt.Fprintf(os.Stderr, "Error: %s\n", errStr)
			if strings.HasPrefix(errStr, "unknown flag:") {
				fmt.Fprintln(os.Stderr, "You're running the community build of Atlas, which may differ from the official version.")
				fmt.Fprintln(os.Stderr, "If this error persists, try installing the official version as a troubleshooting step:\n")
				fmt.Fprintln(os.Stderr, "  curl -sSf https://atlasgo.sh | sh\n")
				fmt.Fprintln(os.Stderr, "More installation options: https://atlasgo.io/docs#installation")
			}
		} else {
			fmt.Fprintf(os.Stderr, "Error: %s\n", errStr)
		}
		os.Exit(1)
	}
}
EOF"}

